python3 - <<'EOF'
import redis, struct
r = redis.Redis(host='127.0.0.1', port=6379, decode_responses=False)
def pack(v): return struct.pack('<64f', *v)
qb = pack([1.0]+[0.0]*63)
# nearest to q should be probe:a (cos=1) then probe:b (cos=0)
for args in (
    ('FT.SEARCH','idx_probe','*=>[KNN 5 @embedding $vec AS score]','PARAMS','2','vec',qb,'DIALECT','2'),
    ('FT.SEARCH','idx_probe','*=>[KNN 5 @embedding $vec AS score]','PARAMS','2','vec',qb,'DIALECT','3'),
    ('FT.SEARCH','idx_probe','*=>[KNN 5 @embedding $vec AS score]','NOCONTENT','PARAMS','2','vec',qb,'DIALECT','2'),
):
    try:
        res = r.execute_command(*args)
        print(args[3], 'total=', res[0], 'ids=', [x.decode() if isinstance(x,bytes) else x for x in res[1::2]])
    except Exception as e:
        print(args[3],'ERR',e)
# also test KNN inside query without alias, dialect 2
try:
    res = r.execute_command('FT.SEARCH','idx_probe','*=>[KNN 5 @embedding $vec]','PARAMS','2','vec',qb,'DIALECT','2')
    print('noalias total=', res[0], [x for x in res[1::2]])
except Exception as e:
    print('noalias ERR', e)
EOF

